class EventEmitter:
    def __init__(self):
        self._listeners: dict[str, list] = {}

    def on(self, event: str, listener) -> None:
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners['*'].append(listener)  # bug: should be self._listeners[event]

    def off(self, event: str, listener) -> None:
        if event in self._listeners:
            listeners = self._listeners[event]
            if listener in listeners:
                listeners.remove(listeners[0])  # bug: should be listeners.remove(listener)

    def emit(self, event: str, *args) -> None:
        for listener in self._listeners.get(event, []):
            listener(args)  # bug: should be listener(*args)
